import{_ as t,o,c as n,a2 as a}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/en/troubleshooting-report.png",g=JSON.parse('{"title":"Help and troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/troubleshooting.md","filePath":"en/features/troubleshooting.md"}'),i={name:"en/features/troubleshooting.md"};function s(l,e,d,h,c,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="help-and-troubleshooting" tabindex="-1">Help and troubleshooting <a class="header-anchor" href="#help-and-troubleshooting" aria-label="Permalink to &quot;Help and troubleshooting&quot;">​</a></h1><p>The Help menu (user guide, what&#39;s new, About Relio and more); what to do when a file does not open, Relio stops unexpectedly or a database connection fails; the diagnostic log; reporting a problem; where your data is stored; and installing and uninstalling.</p><h2 id="help-menu" tabindex="-1">Help menu <a class="header-anchor" href="#help-menu" aria-label="Permalink to &quot;Help menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>Help › User guide…</td><td><kbd>F1</kbd></td><td>Opens the user guide built into the app. See &quot;User guide&quot; below.</td></tr><tr><td>Help › Keyboard shortcuts…</td><td></td><td>Opens the Shortcuts page of Settings. <a href="/relio/en/features/preferences#shortcuts">Settings › Shortcuts</a></td></tr><tr><td>Help › Open sample ▸</td><td></td><td>Opens the <strong>PostgreSQL — online bookstore</strong> or <strong>MySQL — users and permissions</strong> sample as a copy. <a href="/relio/en/features/file#opening-files">File › Opening files</a></td></tr><tr><td>Help › What&#39;s new…</td><td></td><td>Shows what changed in this version. See &quot;What&#39;s new&quot; below.</td></tr><tr><td>Help › Check for updates…</td><td></td><td>Checks right away whether a new version is available. <a href="/relio/en/features/update#checking-manually">Updates</a></td></tr><tr><td>Help › Report a problem…</td><td></td><td>Opens the window for reporting a problem. See &quot;Reporting a problem&quot; below.</td></tr><tr><td>Help › About Relio</td><td></td><td>The version, <strong>Open releases page</strong>, <strong>Check for updates</strong>, the automatic update check status and <strong>Open source licenses</strong>. See &quot;About Relio&quot; below.</td></tr></tbody></table><h2 id="user-guide" tabindex="-1">User guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User guide&quot;">​</a></h2><p>Help › User guide… (<kbd>F1</kbd>) opens the short guide built into the app in a window. Click a section in the table of contents on the left to jump to it. It works without the internet and follows the app&#39;s display language (English if there is no guide in that language). This site has the more detailed explanations.</p><h2 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h2><ul><li>The first time you run a newly installed version, the &quot;What&#39;s new — Relio …&quot; window opens once. Turn on <strong>Don&#39;t show again</strong>, shown only then, before closing, and it will not open by itself for later versions.</li><li>Open it again at any time with Help › What&#39;s new….</li><li>This version&#39;s changes are expanded; under <strong>Earlier versions</strong>, the last five are folded into &quot;version · one-line summary&quot; lines that expand when clicked. <strong>Show full change history</strong> expands the remaining versions inside the app (nothing is opened on the internet).</li><li>The bottom of the window shows the current version, an <strong>Open releases page</strong> link and a <strong>Check for updates</strong> button.</li></ul><h2 id="about-relio" tabindex="-1">About Relio <a class="header-anchor" href="#about-relio" aria-label="Permalink to &quot;About Relio&quot;">​</a></h2><p>Help › About Relio shows the version, an <strong>Open releases page</strong> link, a <strong>Check for updates</strong> button and a line with the automatic update check status (&quot;On&quot;, &quot;Off&quot; or &quot;Not set (off)&quot;). Click <strong>Open source licenses</strong> to read the full license texts of the open source components Relio uses in a read-only window.</p><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>A file does not open</td><td>The error window shows the line and column. Files with an abnormal structure, such as extremely deep nesting, are refused for safety. If the file was repaired while opening, review the repairs. <a href="/relio/en/features/file#opening-a-damaged-file">File › Opening a damaged file</a></td></tr><tr><td>Relio says another program changed the file</td><td>When you return to the window, Relio asks whether to reload. If you have unsaved changes, choose <strong>Merge…</strong> (combine your changes with the outside changes at the model level) · <strong>Reload (discard my changes)</strong> · <strong>Keep my changes</strong>.</td></tr><tr><td>A file does not open after a Git merge</td><td>If it still has conflict markers (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>), the notice takes you straight to <strong>Resolve Git merge conflict…</strong>. For a file broken by a line-based &quot;accept both&quot;, the repairs show which tables and columns were affected, and <strong>Redo the merge at the model level</strong> merges it again. <a href="/relio/en/features/git#merging">Git and merging</a></td></tr><tr><td>Relio stopped unexpectedly</td><td>When you start it again, it offers to recover from the automatic backup. Backups are also in the <code>backup</code> folder of the settings folder. <a href="/relio/en/features/file#automatic-backup-and-recovery">File › Automatic backup and recovery</a></td></tr><tr><td>Cannot connect to a database</td><td>Check the server, port, database name and firewall. For servers with a self-signed certificate, turn on <strong>Trust server certificate (self-signed)</strong> under Advanced ▾ in the connection dialog. For Oracle, check that the Instant Client folder is registered; for Db2, Informix and MS Access, check that the ODBC driver is installed. <a href="/relio/en/features/database">Databases</a></td></tr><tr><td>A notice says something is not used for security reasons</td><td>A driver file, network path or DSN file written in the document was blocked. If you trust the value, register it in Settings or enter it directly in the connection dialog.</td></tr><tr><td>Windows warning when running the installer</td><td>The installer is not code-signed yet, so a &quot;Windows protected your PC&quot; window may appear. Check that the file came from where you expected, then click <strong>More info → Run anyway</strong>. If your company PC blocks unsigned programs, ask your IT administrator.</td></tr><tr><td>The screen text is in the wrong language</td><td>Choose the display language in Tools › Settings › General.</td></tr><tr><td>The new version check does not work</td><td><a href="/relio/en/features/update#when-the-check-fails">Updates › When the check fails</a></td></tr><tr><td>Types look empty when opened in ERMaster</td><td>See <a href="#types-look-empty-in-ermaster">Types look empty in ERMaster</a> below.</td></tr><tr><td>Git shows the whole file as changed on every save</td><td>The line endings differ. Add <code>*.erm text eol=lf</code> to <code>.gitattributes</code>. <a href="/relio/en/quick/git#preparing-the-repository">Working together with Git</a></td></tr></tbody></table><h3 id="types-look-empty-in-ermaster" tabindex="-1">Types look empty in ERMaster <a class="header-anchor" href="#types-look-empty-in-ermaster" aria-label="Permalink to &quot;Types look empty in ERMaster&quot;">​</a></h3><p>Columns that use a type only Relio has (for example <code>json</code>, <code>jsonb</code> or <code>vector</code>) show an empty type field when opened in ERMaster. In the type list of the column properties dialog, such types carry a note saying they look empty in ERMaster, so you know in advance. They work fine in Relio, but if your team mixes ERMaster and Relio, choose types that both tools have.</p><h2 id="diagnostic-log" tabindex="-1">Diagnostic log <a class="header-anchor" href="#diagnostic-log" aria-label="Permalink to &quot;Diagnostic log&quot;">​</a></h2><ul><li>Relio keeps diagnostic information such as errors and start-up time only in the <code>logs</code> folder of its settings folder on this PC (last 7 days, 5 MB in total).</li><li>It is never sent over the internet and contains no file contents, table names, paths or user names.</li><li>If Relio closed unexpectedly, a bar at the bottom of the window tells you once the next time it starts, with a shortcut to <strong>Report a problem…</strong>.</li><li>If you do not want a log, turn off <strong>Keep a diagnostic log</strong> in Tools › Settings › General › Diagnostics and remove existing files with <strong>Delete diagnostic log</strong>.</li></ul><h2 id="reporting-a-problem" tabindex="-1">Reporting a problem <a class="header-anchor" href="#reporting-a-problem" aria-label="Permalink to &quot;Reporting a problem&quot;">​</a></h2><p>Open Help › Report a problem…. The window shows the Relio version and Windows version, and fields to fill in (Steps to reproduce · Expected behavior · Actual behavior).</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td>Report on GitHub</td><td>Opens the GitHub new issue page in your default browser. The version information is filled into the form automatically (a GitHub account is needed).</td></tr><tr><td>Copy report details</td><td>When you cannot use GitHub, copies the same version information and fields so you can paste them into an email or chat.</td></tr><tr><td>Save anonymized copy…</td><td>Saves a copy of the open document with names, descriptions, notes, default values and so on removed (only the structure remains). The current document is not changed.</td></tr><tr><td>Open diagnostic log folder · Copy recent log</td><td>See the diagnostic log files, or copy the last 200 lines to attach to your report.</td></tr></tbody></table><ul><li>Either way, file contents, paths and user names are not included.</li><li>Please first check whether the same problem happens with a sample (Help › Open sample ▸). If it reproduces with a sample, we can check it quickly.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Do not upload company <code>.erm</code> files or screenshots. The table structure itself is company information. If the problem is caused by a file, attach a copy made with <strong>Save anonymized copy…</strong>.</p></div><figure class="shot" data-scene="troubleshooting-report"><img src="'+r+'" alt="Help › Report a problem — version information, ways to report and the diagnostic log buttons" loading="lazy"><figcaption>Help › Report a problem — version information, ways to report and the diagnostic log buttons</figcaption></figure><h2 id="where-your-data-is-stored" tabindex="-1">Where your data is stored <a class="header-anchor" href="#where-your-data-is-stored" aria-label="Permalink to &quot;Where your data is stored&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Models</td><td>The <code>.erm</code> files you save</td></tr><tr><td>App settings · connection list · recent files · per-file records (DDL target version · text export settings · design check ignores and so on)</td><td><code>%APPDATA%\\Relio</code></td></tr><tr><td>Automatic backups (latest 10 per file)</td><td><code>%APPDATA%\\Relio\\backup</code></td></tr><tr><td>Diagnostic log (last 7 days)</td><td><code>%APPDATA%\\Relio\\logs</code></td></tr><tr><td>Database passwords</td><td>Windows Credential Manager (entries starting with <code>relio:</code>) — inside the <code>.erm</code> if turned on per file</td></tr></tbody></table><p>Apart from checking for new versions (only when you turn it on or check yourself), Relio never connects to the internet on its own, and never sends usage data, error reports or file contents anywhere.</p><h2 id="installing-and-uninstalling" tabindex="-1">Installing and uninstalling <a class="header-anchor" href="#installing-and-uninstalling" aria-label="Permalink to &quot;Installing and uninstalling&quot;">​</a></h2><ul><li><strong>Install</strong> — Run the installer (<code>Relio_&lt;version&gt;_x64-setup.exe</code>). It installs for the current user only, without administrator rights. You choose whether to add a desktop shortcut during setup.</li><li><strong>Portable version</strong> — Unzip <code>Relio_&lt;version&gt;_x64_portable.zip</code> and run <code>relio.exe</code>. It uses the same settings folder as the installed version.</li><li><strong>Supported</strong> — Windows 10 and 11 (64-bit). Microsoft Edge WebView2, which Relio uses to display its interface, is built into Windows 10 and 11.</li><li><strong>Update</strong> — Install from inside Relio, or simply run a new installer; it installs over the old version and keeps your settings. <a href="/relio/en/features/update">Updates</a></li><li><strong>Uninstall</strong> — Remove Relio in Windows Settings › Apps. Settings, the connection list and backups (<code>%APPDATA%\\Relio</code>) remain and are used again if you reinstall.</li><li><strong>Remove everything</strong> — After uninstalling, delete the <code>%APPDATA%\\Relio</code> folder and the Windows Credential Manager entries starting with <code>relio:</code> (you can also delete them first in Tools › Settings › Password).</li></ul>',27)])])}const f=t(i,[["render",s]]);export{g as __pageData,f as default};
